const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const depok = ee.Geometry.Point(106.8318, -6.3887); // Coordinates for Depok, Indonesia
    const bufferRadius = 10000; // 10 km buffer around Depok
    const geometry = depok.buffer(bufferRadius);

    const year1990_start = '1990-06-01';
    const year1990_end = '1990-08-31';
    const year2019_start = '2019-06-01';
    const year2019_end = '2019-08-31';

    const scale = 30; // Landsat resolution

    // Cloud masking function for Landsat 5/7/8 Surface Reflectance (Collection 1, Tier 1)
    function maskL8sr(image) {
      // Bits 3 and 5 are cloud shadow and cloud, respectively.
      var cloudShadowBitMask = (1 << 3);
      var cloudsBitMask = (1 << 5);
      // Both flags should be set to zero, indicating clear conditions.
      var qa = image.select('pixel_qa');
      var mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
      return image.updateMask(mask)
          .select(['B[1-7]'])
          .copyProperties(image, ['system:time_start']);
    }

    // Function to calculate NDVI
    function addNDVI(image) {
      // For Landsat 5 and 8, NIR is B4, Red is B3.
      // For Landsat 8, NIR is B5, Red is B4.
      // Need to adjust band names based on collection.
      var nir, red;
      if (image.get('satellite').getInfo() === 'LANDSAT_5') {
        nir = 'B4';
        red = 'B3';
      } else if (image.get('satellite').getInfo() === 'LANDSAT_8') {
        nir = 'B5';
        red = 'B4';
      } else {
        // Default or error handling
        return image.addBands(ee.Image(-999).rename('NDVI')); // Indicate error
      }
      return image.normalizedDifference([nir, red]).rename('NDVI');
    }

    // 2. Data Acquisition & Check for 1990 (Landsat 5)
    let collection1990 = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
        .filterDate(year1990_start, year1990_end)
        .filterBounds(geometry)
        .map(maskL8sr)
        .map(addNDVI);

    const count1990 = await collection1990.size().getInfo();
    if (count1990 === 0) {
      console.log("No images found for 1990-06-01 to 1990-08-31 after cloud mask.");
      console.log("C1");
      return;
    }

    const image1990 = collection1990.median().clip(geometry);

    // Check if the median image is empty after cloud masking
    const pixels1990 = await image1990.select('NDVI').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    if (pixels1990 === 0) {
      console.log("Images found for 1990 but no valid pixels remain after cloud masking.");
      console.log("C2");
      return;
    }

    const ndvi1990 = await image1990.select('NDVI').reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    // 2. Data Acquisition & Check for 2019 (Landsat 8)
    let collection2019 = ee.ImageCollection('LANDSAT/LC08/C01/T1_SR')
        .filterDate(year2019_start, year2019_end)
        .filterBounds(geometry)
        .map(maskL8sr)
        .map(addNDVI);

    const count2019 = await collection2019.size().getInfo();
    if (count2019 === 0) {
      console.log("No images found for 2019-06-01 to 2019-08-31 after cloud mask.");
      console.log("C1");
      return;
    }

    const image2019 = collection2019.median().clip(geometry);

    // Check if the median image is empty after cloud masking
    const pixels2019 = await image2019.select('NDVI').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    if (pixels2019 === 0) {
      console.log("Images found for 2019 but no valid pixels remain after cloud masking.");
      console.log("C2");
      return;
    }

    const ndvi2019 = await image2019.select('NDVI').reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    // 4. Validation & Final Answer
    if (ndvi1990 === null || isNaN(ndvi1990) || ndvi2019 === null || isNaN(ndvi2019)) {
      console.log("NDVI calculation returned null or NaN.");
      console.log("C3");
      return;
    }

    console.log(`1990 Images: ${count1990} (Valid Pixels: ${pixels1990})`);
    console.log(`2019 Images: ${count2019} (Valid Pixels: ${pixels2019})`);
    console.log(`Mean NDVI 1990: ${ndvi1990.toFixed(3)}`);
    console.log(`Mean NDVI 2019: ${ndvi2019.toFixed(3)}`);

    if (ndvi2019 < ndvi1990) {
      console.log("A"); // Yes, vegetation cover was lower in 2019
    } else {
      console.log("B"); // No, vegetation cover was not lower in 2019
    }

  } catch (error) {
    console.log("D"); // General error for code issues
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
